{
     "title": "CSCI-521: Principles of Data Cleaning and Preparation",
     "learningObjectives": [
       "Define the knowledge discovery process and explain how data cleaning serves as a foundational step for subsequent data mining.",
       "Apply techniques for data extraction, cleaning, integration, and transformation across numeric, unstructured, text, and web data formats.",
       "Evaluate ethical considerations in data preparation and mining, ensuring compliance with data integrity and privacy standards."
     ],
     "beats": [
       {
         "title": "Course Foundations and Scope",
         "claim": "CSCI-521 introduces the knowledge discovery process and establishes data cleaning as a prerequisite for effective data mining.",
         "example": "Students will review the official course catalog to confirm that data cleaning projects and a paper are required for credit.",
         "visualDirection": "Display the official course catalog excerpt highlighting the knowledge discovery process and required deliverables.",
         "sourceIds": ["rit-csci-521"]
       },
       {
         "title": "Data Exploration and Its Role",
         "claim": "Data exploration is a critical phase that identifies patterns, anomalies, and quality issues before transformation.",
         "example": "Instructor will demonstrate how exploratory data analysis reveals missing values and outliers in a sample dataset.",
         "visualDirection": "Show a split-screen comparison of raw data versus explored data highlighting identified anomalies.",
         "sourceIds": ["rit-csci-521"]
       },
       {
         "title": "Data Extraction and Cleaning",
         "claim": "Data extraction and cleaning involve removing irrelevant records, correcting errors, and standardizing formats.",
         "example": "Students will practice extracting structured data from a CSV file and removing duplicate rows using standard cleaning techniques.",
         "visualDirection": "Animate the step-by-step removal of duplicate rows and standardization of date formats in a spreadsheet.",
         "sourceIds": ["rit-csci-521"]
       },
       {
         "title": "Data Integration and Transformation",
         "claim": "Data integration combines multiple data sources, while transformation converts data into a consistent format for analysis.",
         "example": "Instructor will demonstrate merging two relational tables and converting categorical variables into numeric codes.",
         "visualDirection": "Display a before-and-after table showing merged columns and transformed categorical values.",
         "sourceIds": ["rit-csci-521"]
       },
       {
         "title": "Handling Numeric Data",
         "claim": "Numeric data requires specific cleaning techniques such as imputation for missing values and normalization for scale consistency.",
         "example": "Students will calculate the mean and median to impute missing numeric values and apply min-max normalization to a dataset.",
         "visualDirection": "Show a bar chart comparing raw numeric values versus normalized values ranging from 0 to 1.",
         "sourceIds": ["rit-csci-521"]
       },
       {
         "title": "Handling Unstructured and Text Data",
         "claim": "Unstructured and text data require preprocessing steps like tokenization, stop-word removal, and stemming before analysis.",
         "example": "Instructor will demonstrate converting a paragraph of text into a list of tokens and removing common stop words.",
         "visualDirection": "Display a word cloud transitioning from raw text to a cleaned token list with stop words highlighted.",
         "sourceIds": ["rit-csci-521"]
       },
       {
         "title": "Handling Web Data",
         "claim": "Web data extraction involves parsing HTML, handling dynamic content, and managing rate limits to ensure data quality.",
         "example": "Students will scrape a static webpage, parse the HTML structure, and extract structured records while respecting server rate limits.",
         "visualDirection": "Show a flowchart of the web scraping process from request to parsed JSON output.",
         "sourceIds": ["rit-csci-521"]
       },
       {
         "title": "Data Integrity and Constraints",
         "claim": "Data integrity is maintained through constraints, indexes, and validation rules that enforce data quality standards.",
         "example": "Instructor will demonstrate how primary keys and foreign keys prevent duplicate and orphaned records in a relational database.",
         "visualDirection": "Display a database schema diagram highlighting primary key and foreign key relationships.",
         "sourceIds": ["postgresql-documentation"]
       },
       {
         "title": "Ethical Issues in Data Preparation",
         "claim": "Ethical considerations in data preparation include privacy protection, bias mitigation, and responsible data usage.",
         "example": "Students will review a case study on anonymizing personal data and ensuring fair representation in cleaned datasets.",
         "visualDirection": "Show a checklist of ethical guidelines for data preparation and mining.",
         "sourceIds": ["rit-csci-521"]
       },
       {
         "title": "Practical Analysis Checklist",
         "claim": "A practical analysis checklist ensures all data cleaning steps are verified, documented, and aligned with course objectives.",
         "example": "Students will complete a checklist verifying extraction accuracy, cleaning completeness, transformation consistency, and ethical compliance.",
         "visualDirection": "Display a printable checklist template with checkboxes for each verification step.",
         "sourceIds": ["rit-csci-521"]
       }
     ]
   }
